class Solution { public:
 int minimumChanges(string s,int k){
  int n=s.size(),INF=100000000;vector<vector<int>> cost(n,vector<int>(n+1,INF));
  for(int l=0;l<n;++l)for(int r=l+2;r<=n;++r){int len=r-l;
   for(int d=1;d<len;++d)if(len%d==0){int changes=0;
    for(int offset=0;offset<d;++offset){int a=l+offset,b=l+offset+(len/d-1)*d;
     while(a<b){changes+=s[a]!=s[b];a+=d;b-=d;}}
    cost[l][r]=min(cost[l][r],changes);
   }
  }
  vector<vector<int>> dp(k+1,vector<int>(n+1,INF));dp[0][0]=0;
  for(int groups=1;groups<=k;++groups)for(int r=2*groups;r<=n;++r)
   for(int l=2*(groups-1);l<=r-2;++l)if(dp[groups-1][l]!=INF)
    dp[groups][r]=min(dp[groups][r],dp[groups-1][l]+cost[l][r]);
  return dp[k][n];
 }
};
